import{_ as r,C as s,o as e,c as d,j as i,a as o,E as t,a2 as n}from"./chunks/framework.C21TwvGF.js";const D=JSON.parse('{"title":"9-dars (Mentor). 9-dars: Ikonka, tugma va navigatsiya elementlarini dizayni (UI Kit)","description":"","frontmatter":{"title":"9-dars (Mentor). 9-dars: Ikonka, tugma va navigatsiya elementlarini dizayni (UI Kit)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"10-sinf (UX/UI)","link":"/mentor/10-sinf-uxui/"},"week":{"n":3,"link":"/mentor/10-sinf-uxui/hafta-03/"},"g":9,"title":"9-dars: Ikonka, tugma va navigatsiya elementlarini dizayni (UI Kit)","lead":"Ikonka, tugma va navigatsiya elementlarini dizayni (UI Kit)","slide":"/slaydlar/10-sinf-uxui/hafta-03/dars-3.html","test":"/slaydlar/10-sinf-uxui/hafta-03/dars-3-test.html","student_link":"/10-sinf-uxui/hafta-03/dars-3","tabs":[{"g":7,"link":"/mentor/10-sinf-uxui/hafta-03/dars-1","current":false},{"g":8,"link":"/mentor/10-sinf-uxui/hafta-03/dars-2","current":false},{"g":9,"link":"/mentor/10-sinf-uxui/hafta-03/dars-3","current":true}],"prev":{"g":8,"title":"8-dars: Grid tizimlari va kompozitsiya","link":"/mentor/10-sinf-uxui/hafta-03/dars-2"},"next":null}},"headers":[],"relativePath":"mentor/10-sinf-uxui/hafta-03/dars-3.md","filePath":"mentor/10-sinf-uxui/hafta-03/dars-3.md"}'),u={name:"mentor/10-sinf-uxui/hafta-03/dars-3.md"},h={class:"blk"},g={id:"darsning-maqsadi",tabindex:"-1"},m={class:"blk"},k={id:"kutilayotgan-natijalar-o-quvchi-bilishi-kerak",tabindex:"-1"},y={class:"blk"},b={id:"kerakli-jihozlar-va-vositalar",tabindex:"-1"},q={class:"blk"},c={id:"dars-rejasi-80-daqiqa",tabindex:"-1"},v={class:"blk"},f={id:"nazariy-ma-lumotlar",tabindex:"-1"},p={class:"blk"},x={id:"amaliy-topshiriqlar-va-mashqlar",tabindex:"-1"},z={class:"blk"},T={id:"tezkor-nazorat-savollari",tabindex:"-1"},_={class:"blk"},A={id:"keng-tarqalgan-xatolar-va-ularning-oldini-olish",tabindex:"-1"};function I(F,a,S,P,B,j){const l=s("Icon");return e(),d("div",null,[a[26]||(a[26]=i("p",null,[i("strong",null,"Fan:"),o(" Advanced UX/UI dizayn va Advanced Front-end"),i("br"),i("strong",null,"Sinf:"),o(" 10-sinf"),i("br"),i("strong",null,"Hafta:"),o(" 3-hafta, 3-dars (umumiy 9-dars)"),i("br"),i("strong",null,"Dars davomiyligi:"),o(" 80 daqiqa")],-1)),a[27]||(a[27]=i("hr",null,null,-1)),i("div",h,[i("h2",g,[t(l,{name:"file-text"}),a[0]||(a[0]=o(" Darsning maqsadi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#darsning-maqsadi","aria-label":'Permalink to "<Icon name="file-text" /> Darsning maqsadi"'},"​",-1))]),a[2]||(a[2]=i("p",null,[o("O'quvchilarga raqamli foydalanuvchi interfeysining (UI) eng muhim interaktiv bloklari — "),i("strong",null,"tugmalar (buttons)"),o(", "),i("strong",null,"ikonkalar (icons)"),o(" va "),i("strong",null,"navigatsiya elementlari"),o("ni professional darajada loyihalashni o'rgatish; asosiy va qo'shimcha tugma turlari (Primary, Secondary, Tertiary/Ghost, FAB, Icon button, Link), tugmaning 5 ta holati (Enabled, Hover, Focus, Active, Disabled), mobil teginish o'lchamlari (kamida 44px) hamda kontrast talablarini (kamida 4.5:1) tushuntirish; Figma dasturida Auto Layout ("),i("code",null,"Shift + A"),o(") va Variantlar yordamida qayta ishlatiluvchi yaxlit "),i("strong",null,"UI Kit"),o(" komponentlarini yaratish amaliy ko'nikmalarini shakllantirish.")],-1)),a[3]||(a[3]=i("hr",null,null,-1))]),i("div",m,[i("h2",k,[t(l,{name:"file-text"}),a[4]||(a[4]=o(" Kutilayotgan natijalar (O'quvchi bilishi kerak) ",-1)),a[5]||(a[5]=i("a",{class:"header-anchor",href:"#kutilayotgan-natijalar-o-quvchi-bilishi-kerak","aria-label":`Permalink to "<Icon name="file-text" /> Kutilayotgan natijalar (O'quvchi bilishi kerak)"`},"​",-1))]),a[6]||(a[6]=n("<ul><li>Foydalanuvchi interfeysida tugmalarning ierarxiyasini (Primary, Secondary, Tertiary/Ghost) ajrata olish;</li><li>Mobil va veb interfeyslardagi maxsus tugmalarning (FAB, Icon button, Link) vazifasini tushunish;</li><li>Tugmaning 5 ta holatini (Enabled, Hover, Focus, Active, Disabled) va nima uchun Focus holati accessibility uchun zarurligini bilish;</li><li>Tugma yorlig&#39;i (label) qoidalarini (fe&#39;l shakli, qisqalik, 14–18px semibold shrift) amalda to&#39;g&#39;ri tanlash;</li><li>Matn va tugma foni o&#39;rtasidagi rang kontrasti kamida 4.5:1 bo&#39;lishi shartligini bilish;</li><li>Mobilda teginish maydoni (touch target) kamida 44px bo&#39;lishi lozimligini o&#39;rganish;</li><li>Ikonkalar bilan ishlash qoidalarini (tanish metaforalardan foydalanish, yangi belgi ixtiro qilmaslik, matnli yorliqlar bilan quvvatlash) bilish;</li><li>Sayt va ilovalardagi asosiy navigatsiya bloklarini (Header/Logo, Gorizontal menyu, Qidiruv, Pastki tab-bar, Non ushoqlari) to&#39;g&#39;ri loyihalay olish;</li><li>Figmada Auto Layout (<code>Shift + A</code>) yordamida responsiv tugmalar va UI Kit yaratishni amalda bajara olish.</li></ul><hr>",2))]),i("div",y,[i("h2",b,[t(l,{name:"file-text"}),a[7]||(a[7]=o(" Kerakli jihozlar va vositalar ",-1)),a[8]||(a[8]=i("a",{class:"header-anchor",href:"#kerakli-jihozlar-va-vositalar","aria-label":'Permalink to "<Icon name="file-text" /> Kerakli jihozlar va vositalar"'},"​",-1))]),a[9]||(a[9]=i("ul",null,[i("li",null,"Kompyuter yoki noutbuk (har bir o'quvchi uchun);"),i("li",null,"Internet tarmog'i va veb-brauzer;"),i("li",null,"Figma akkaunti (veb yoki desktop ilovasi);"),i("li",null,"WCAG kontrast tekshiruvchi plaginlar (masalan, Stark yoki Contrast Checker);"),i("li",null,"Proyektor yoki monitor (namoyish uchun).")],-1)),a[10]||(a[10]=i("hr",null,null,-1))]),i("div",q,[i("h2",c,[t(l,{name:"file-text"}),a[11]||(a[11]=o(" Dars rejasi (80 daqiqa) ",-1)),a[12]||(a[12]=i("a",{class:"header-anchor",href:"#dars-rejasi-80-daqiqa","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi (80 daqiqa)"'},"​",-1))]),a[13]||(a[13]=n('<table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Tavsif</th></tr></thead><tbody><tr><td><strong>00–10 min</strong></td><td>Tashkiliy qism va takrorlash</td><td>Grid tizimlari, 12 ustunli desktop va 8pt masofa qoidalari bo&#39;yicha savol-javob</td></tr><tr><td><strong>10–25 min</strong></td><td>Yangi mavzu: Tugmalar va ularning UIdagi roli</td><td>Tugmalar ierarxiyasi (Primary, Secondary, Tertiary), FAB, Icon button, Link</td></tr><tr><td><strong>25–40 min</strong></td><td>Tugma dizayni omillari va 5 ta holati</td><td>Shakl, burchak radiusi, yorliq qoidalari, 5 ta holat (Enabled, Hover, Focus, Active, Disabled), 44px qoidasi</td></tr><tr><td><strong>40–55 min</strong></td><td>Ikonkalar va navigatsiya bloklari</td><td>Universal ikonalar, gorizontal menyu, qidiruv bloki, mobil bottom bar</td></tr><tr><td><strong>55–75 min</strong></td><td>Amaliy mashg&#39;ulot (Figma UI Kit)</td><td>Auto Layout bilan Primary va Secondary tugmalarni yaratish, barcha holatlarini (Variants) yig&#39;ish</td></tr><tr><td><strong>75–80 min</strong></td><td>Xulosa va darsni yakunlash</td><td>Asosiy xulosalar, tezkor nazorat savollari va uyga vazifa topshirig&#39;i</td></tr></tbody></table><hr>',2))]),i("div",v,[i("h2",f,[t(l,{name:"file-text"}),a[14]||(a[14]=o(" Nazariy ma'lumotlar ",-1)),a[15]||(a[15]=i("a",{class:"header-anchor",href:"#nazariy-ma-lumotlar","aria-label":`Permalink to "<Icon name="file-text" /> Nazariy ma'lumotlar"`},"​",-1))]),a[16]||(a[16]=n('<h3 id="_1-tugmalar-buttons-va-ularning-uidagi-ahamiyati" tabindex="-1">1. Tugmalar (Buttons) va ularning UIdagi ahamiyati <a class="header-anchor" href="#_1-tugmalar-buttons-va-ularning-uidagi-ahamiyati" aria-label="Permalink to &quot;1. Tugmalar (Buttons) va ularning UIdagi ahamiyati&quot;">​</a></h3><p>Tugmalar — foydalanuvchi interfeysining (UI) eng muhim komponentlaridan biridir. Ular foydalanuvchini harakatga undovchi asosiy vosita (Call to Action — CTA) hisoblanadi. Har qanday interfeysda harakatni amalga oshirish uchun tugmalar ma&#39;lum bir vizual ierarxiya asosida joylashtiriladi.</p><h4 id="asosiy-tugma-turlari" tabindex="-1">Asosiy tugma turlari: <a class="header-anchor" href="#asosiy-tugma-turlari" aria-label="Permalink to &quot;Asosiy tugma turlari:&quot;">​</a></h4><ol><li><strong>Birlamchi tugma (Primary button):</strong><ul><li>Ekrandagi eng muhim amalni bajaradi (masalan: <em>To&#39;lov qilish</em>, <em>Ro&#39;yxatdan o&#39;tish</em>, <em>Formani yuborish</em>).</li><li>Vizual jihatdan eng yorqin, to&#39;liq fonli va diqqatni birinchi bo&#39;lib tortadigan ko&#39;rinishga ega bo&#39;ladi.</li><li>Odatda bir ekranda faqat bitta asosiy Primary tugma bo&#39;lishi tavsiya etiladi.</li></ul></li><li><strong>Ikkinchi darajali tugma (Secondary button):</strong><ul><li>Birlamchi tugmaga nisbatan kamroq muhim, ammo zarur amallarni bajaradi (masalan: <em>Bekor qilish</em>, <em>Qoralama saqlash</em>).</li><li>Odatda konturli (outline) yoki och neytral fonli bo&#39;ladi.</li></ul></li><li><strong>Uchinchi darajali (Tertiary) yoki &quot;Ghost&quot; tugma:</strong><ul><li>Kam ahamiyatli, yordamchi amallar uchun ishlatiladi (masalan: <em>Parolni unutdingizmi?</em>, <em>Tafsilotlar</em>).</li><li>Fonsiz yoki faqat matn ko&#39;rinishida bo&#39;lib, sahifani vizual og&#39;irlashtirmaydi.</li></ul></li></ol><h4 id="qo-shimcha-tugma-turlari" tabindex="-1">Qo&#39;shimcha tugma turlari: <a class="header-anchor" href="#qo-shimcha-tugma-turlari" aria-label="Permalink to &quot;Qo&#39;shimcha tugma turlari:&quot;">​</a></h4><ol><li><strong>FAB (Floating Action Button — Suzuvchi amal tugmasi):</strong><ul><li>Asosan mobil interfeyslarda ekranning pastki o&#39;ng burchagida &quot;suzib turadi&quot;.</li><li>Doira shaklida, soyali (drop shadow) va markazida bitta ikona bo&#39;ladi (masalan, Gmail&#39;dagi <em>Yangi xat yozish</em> tugmasi).</li></ul></li><li><strong>Ikona tugma (Icon button):</strong><ul><li>Matnsiz, faqat piktogramma shaklidagi tugma (qidiruv lupasi, savatcha, bildirishnoma qo&#39;ng&#39;irog&#39;i). Joy tejaydi, biroq faqat 100% tushunarli ramzlar uchun ishlatilishi shart.</li></ul></li><li><strong>Havola tugma (Link button):</strong><ul><li>Tashqi ko&#39;rinishi giperhavolaga o&#39;xshash, foydalanuvchini boshqa sahifa yoki bo&#39;limga yo&#39;naltiradi.</li></ul></li></ol><hr><h3 id="_2-tugma-dizaynining-asosiy-omillari" tabindex="-1">2. Tugma dizaynining asosiy omillari <a class="header-anchor" href="#_2-tugma-dizaynining-asosiy-omillari" aria-label="Permalink to &quot;2. Tugma dizaynining asosiy omillari&quot;">​</a></h3><ol><li><strong>Shakli va burchak radiusi (Corner radius):</strong><ul><li>To&#39;g&#39;ri to&#39;rtburchak (0–4px radius): jiddiy, moliyaviy va korporativ uslub;</li><li>Katta radius (8–16px): zamonaviy, qulay va do&#39;stona muhit;</li><li>To&#39;liq yumaloq (Pill / 999px radius): e&#39;tiborni kuchli tortadi, CTA uchun ayni muddao.</li></ul></li><li><strong>Tugma yorlig&#39;i (Label):</strong><ul><li>Qisqa va fe&#39;l shaklida bo&#39;lishi shart (<em>Yuborish</em>, <em>Xarid qilish</em>, <em>Yuklab olish</em>);</li><li>O&#39;qilishi oson shriftlar (Roboto, Inter, Lato) tanlanadi, o&#39;lchami 14–18px, vazni Medium yoki Semibold bo&#39;ladi;</li><li>Bir butun platforma bo&#39;ylab atamalar bir xil bo&#39;lishi lozim (bir sahifada &quot;Yuborish&quot;, boshqa sahifada &quot;Jo&#39;natish&quot; deyilmasligi kerak).</li></ul></li><li><strong>Rang va kontrast talabi (WCAG AA):</strong><ul><li>Tugma matni va uning foni o&#39;rtasidagi kontrast nisbati kamida <strong>4.5 : 1</strong> bo&#39;lishi shart.</li><li>Ranglar psixologik ma&#39;noga ega: qizil — xavfli yoki bekor qiluvchi amal (Delete, Logout), yashil/ko&#39;k — muvaffaqiyatli tasdiq (Confirm, Pay).</li></ul></li><li><strong>Ergonomika va o&#39;lcham (44px qoidasi):</strong><ul><li>Tugmaning balandligi odatda 32–56px bo&#39;ladi.</li><li><strong>Mobil interfeyslarda odam barmog&#39;i bilan bexato bosishi uchun minimal teginish maydoni (touch target) kamida 44×44px bo&#39;lishi shart!</strong></li></ul></li></ol><hr><h3 id="_3-tugmaning-5-ta-holati-button-states" tabindex="-1">3. Tugmaning 5 ta holati (Button States) <a class="header-anchor" href="#_3-tugmaning-5-ta-holati-button-states" aria-label="Permalink to &quot;3. Tugmaning 5 ta holati (Button States)&quot;">​</a></h3><p>Har bir professional tugma interfeysda kamida 5 ta holatga ega bo&#39;lishi kerak:</p><ol><li><strong>Enabled (Default / Normal):</strong> Tugmaning odatiy, bosishga tayyor turgan holati.</li><li><strong>Hover:</strong> Foydalanuvchi sichqoncha kursorini tugma ustiga keltirgandagi holat (fon rangi 10-15% ga to&#39;qroq yoki ochroq bo&#39;ladi).</li><li><strong>Focus:</strong> Foydalanuvchi klaviaturadagi <code>Tab</code> tugmasi orqali tugmaga kelganda paydo bo&#39;ladigan holat (konturli halqa/ring). Bu imkoniyati cheklangan (accessibility) foydalanuvchilar uchun hayotiy muhim!</li><li><strong>Active (Pressed):</strong> Tugma aynan bosilgan lahzadagi reaksiyasi (kichrayish, chuqurlashish yoki rang qorayishi).</li><li><strong>Disabled:</strong> Tugma hozircha ishlamaydigan holat (masalan, forma to&#39;liq to&#39;ldirilmaguncha). Odatda 30-40% xira kulrang bo&#39;ladi va kursor &quot;not-allowed&quot; belgisiga aylanadi.</li></ol><hr><h3 id="_4-ikonkalar-icons-bilan-ishlash-qoidalari" tabindex="-1">4. Ikonkalar (Icons) bilan ishlash qoidalari <a class="header-anchor" href="#_4-ikonkalar-icons-bilan-ishlash-qoidalari" aria-label="Permalink to &quot;4. Ikonkalar (Icons) bilan ishlash qoidalari&quot;">​</a></h3><ul><li><strong>Tanish metaforalar:</strong> Odamlar ko&#39;nikkan belgilardan foydalaning. Qidiruv uchun lupa, savat uchun aravacha, sozlamalar uchun tishli g&#39;ildirak.</li><li><strong>Yangi ramzlar o&#39;ylab topmang:</strong> Notanish ikonka foydalanuvchini adashtiradi va qo&#39;rquv uyg&#39;otadi.</li><li><strong>Matn bilan birga qo&#39;llash:</strong> Iloji boricha ikonkani qisqa matnli yorliq bilan birga ishlating. Matnsiz ikona faqat hammaga ma&#39;lum funksiyalarda (qidiruv, profil, uy) o&#39;zini oqlaydi.</li><li><strong>Birlik va o&#39;lcham:</strong> Barcha ikonalar bitta o&#39;lchamdagi bounding box (masalan, 24×24px) ichida va bir xil chiziq qalinligida (stroke width) chizilishi shart.</li></ul><hr><h3 id="_5-asosiy-navigatsiya-bloklari-va-ui-kit-tushunchasi" tabindex="-1">5. Asosiy navigatsiya bloklari va UI Kit tushunchasi <a class="header-anchor" href="#_5-asosiy-navigatsiya-bloklari-va-ui-kit-tushunchasi" aria-label="Permalink to &quot;5. Asosiy navigatsiya bloklari va UI Kit tushunchasi&quot;">​</a></h3><ul><li><strong>Logo / &quot;Asosiy sahifaga&quot; bloki:</strong> Sahifaning yuqori chap burchagida joylashadi, har doim bosh sahifaga qaytaradi.</li><li><strong>Gorizontal navigatsiya paneli (Navbar):</strong> Asosiy bo&#39;limlarga o&#39;tish giperhavolalari ro&#39;yxati.</li><li><strong>Qidiruv va tezkor harakatlar (Search &amp; Action):</strong> Odatda o&#39;ng burchakda profil va savatcha bilan birga joylashadi.</li><li><strong>Mobil pastki menyu (Bottom Navigation Bar):</strong> Mobilda bir qo&#39;l bilan boshqarish uchun pastki qismda 3–5 ta eng muhim tugmani jamlaydi.</li><li><strong>Non ushoqlari (Breadcrumbs):</strong> Ierarxik chuqur kataloglarda foydalanuvchiga hozir qayerda ekanini ko&#39;rsatadi (<code>Bosh sahifa &gt; Katalog &gt; Noutbuklar</code>).</li><li><strong>UI Kit:</strong> Dizayn loyihasida ishlatiladigan barcha tugmalar, ikonalar, forma maydonlari va navigatsiya elementlarining yagona, standartlashtirilgan komponentlar to&#39;plamidir. Figmada komponentlar (<code>Ctrl + Alt + K</code>) va variantlar orqali boshqariladi.</li></ul><hr>',20))]),i("div",p,[i("h2",x,[t(l,{name:"file-text"}),a[17]||(a[17]=o(" Amaliy topshiriqlar va mashqlar ",-1)),a[18]||(a[18]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-mashqlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va mashqlar"'},"​",-1))]),a[19]||(a[19]=n('<h3 id="_1-topshiriq-interfeysdagi-amallar-uchun-tugma-turini-to-g-ri-tanlash-oson" tabindex="-1">1-topshiriq. Interfeysdagi amallar uchun tugma turini to&#39;g&#39;ri tanlash (oson) <a class="header-anchor" href="#_1-topshiriq-interfeysdagi-amallar-uchun-tugma-turini-to-g-ri-tanlash-oson" aria-label="Permalink to &quot;1-topshiriq. Interfeysdagi amallar uchun tugma turini to&#39;g&#39;ri tanlash (oson)&quot;">​</a></h3><p>Quyidagi 4 ta amal uchun tugma toifasini (Primary, Secondary, Ghost, FAB, Destructive) to&#39;g&#39;ri biriktiring va tanlovingizni asoslang:</p><ol><li>Internet-do&#39;konda buyurtmani rasmiylashtirish va to&#39;lash tugmasi;</li><li>Shaxsiy profilni butunlay o&#39;chirib yuborish (Delete Account) tugmasi;</li><li>Mobil messenjerda tezda yangi xat yoki suhbat boshlash tugmasi;</li><li>Mahsulot kartochkasi ostidagi &quot;Mahsulot haqida to&#39;liq sharhlar&quot; havolasi.</li></ol><p><strong>Yechim:</strong></p><ol><li><strong>To&#39;lov qilish:</strong> <code>Primary button</code> — ekrandagi eng asosiy maqsad va harakatga chaqiruv (CTA);</li><li><strong>Profilni o&#39;chirish:</strong> <code>Destructive (Qizil) Secondary yoki Alert tugmasi</code> — xato bosilib ketmasligi uchun uni Primary qilib ajratilmaydi, aksincha ikkilamchi qilib, qizil rangda ogohlantirish beriladi;</li><li><strong>Yangi xat yozish:</strong> <code>FAB (Floating Action Button)</code> — mobil ekranning pastki o&#39;ng burchagida doimiy suzib turuvchi, bitta harakat bilan yangi xat ochadigan doiraviy tugma;</li><li><strong>To&#39;liq sharhlar:</strong> <code>Ghost / Link tugma</code> — vizual og&#39;irlik tug&#39;dirmaydigan minimal ko&#39;rinishdagi havola tugma.</li></ol><hr><h3 id="_2-topshiriq-tugma-dizaynidagi-xatolarni-tahlil-qilish-va-to-g-rilash-o-rta" tabindex="-1">2-topshiriq. Tugma dizaynidagi xatolarni tahlil qilish va to&#39;g&#39;rilash (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-tugma-dizaynidagi-xatolarni-tahlil-qilish-va-to-g-rilash-o-rta" aria-label="Permalink to &quot;2-topshiriq. Tugma dizaynidagi xatolarni tahlil qilish va to&#39;g&#39;rilash (o&#39;rta)&quot;">​</a></h3><p>Yangi boshlovchi dizayner mobil ilova uchun tugma yaratdi va unda quyidagi xususiyatlar mavjud:</p><ul><li>Tugma balandligi: <code>28px</code>;</li><li>Fon rangi: och sariq (<code>#FEF08A</code>), matn rangi: oq (<code>#FFFFFF</code>);</li><li>Tugma matni: <em>&quot;Iltimos, agar rozi bo&#39;lsangiz, keyingi sahifaga o&#39;tish uchun shu yerni bosing&quot;</em>;</li><li>Faqat bitta holat chizilgan, Hover yoki Focus ko&#39;rsatilmagan.</li></ul><p>Ushbu dizayndagi 4 ta jiddiy xatoni aniqlang va ularni professional qoidalarga moslab to&#39;g&#39;rilang.</p><p><strong>Yechim:</strong></p><ol><li><strong>O&#39;lcham xatosi:</strong> <code>28px</code> mobilda barmoq bilan bosish uchun juda kichik. To&#39;g&#39;rilash: Balandlikni kamida <code>44px</code> (yoki <code>48px</code>) qilish kerak.</li><li><strong>Kontrast xatosi:</strong> Och sariq fondagi oq matn o&#39;qilmaydi (kontrast taxminan 1.2:1 bo&#39;lib, 4.5:1 me&#39;yoridan ancha past). To&#39;g&#39;rilash: Fonni to&#39;q rangga o&#39;zgartirish yoki fon sariq qolsa matnni to&#39;q kulrang/qora (<code>#1F2937</code>) qilish kerak.</li><li><strong>Yorliq (label) xatosi:</strong> Matn juda uzun va noaniq. To&#39;g&#39;rilash: Qisqa fe&#39;lli CTA matn qo&#39;yish kerak: <em>&quot;Davom etish&quot;</em> yoki <em>&quot;Oldinga&quot;</em>.</li><li><strong>Holatlar xatosi:</strong> Tugma bitta holatda qolgan, interaktivlik va accessibility yo&#39;q. To&#39;g&#39;rilash: Kamida 5 ta holatni (Default, Hover, Active, Focus, Disabled) ishlab chiqish kerak.</li></ol><hr><h3 id="_3-topshiriq-figma-dasturida-to-liq-auto-layout-tugma-komponentini-loyihalash-qiyin" tabindex="-1">3-topshiriq. Figma dasturida to&#39;liq Auto Layout tugma komponentini loyihalash (qiyin) <a class="header-anchor" href="#_3-topshiriq-figma-dasturida-to-liq-auto-layout-tugma-komponentini-loyihalash-qiyin" aria-label="Permalink to &quot;3-topshiriq. Figma dasturida to&#39;liq Auto Layout tugma komponentini loyihalash (qiyin)&quot;">​</a></h3><p>Figma dasturida zamonaviy veb va mobil ilovalar uchun moslashuvchan <strong>Primary Button</strong> komponentini loyihalashtiring:</p><ol><li><code>T</code> tugmasi bilan matn yozing va shrift parametrlarini belgilang (Inter, 16px, Semi-bold);</li><li>Auto Layout (<code>Shift + A</code>) qo&#39;llang;</li><li>Ichki masofalarni (Padding) 8pt tizimi bo&#39;yicha kiriting;</li><li>Burchak radiusini (Corner radius) o&#39;rnating;</li><li>Tugmaning barcha 5 ta holati (Enabled, Hover, Focus, Active, Disabled) uchun Variantlar (<code>Create Component Set</code>) yarating.</li></ol><p><strong>Yechim:</strong></p><ol><li><strong>Matn yaratish:</strong> <em>&quot;Saqlash&quot;</em> deb matn yoziladi. Shrift: Inter, 16px, Semibold, rang oq (<code>#FFFFFF</code>).</li><li><strong>Auto Layout qo&#39;shish:</strong> Matn tanlanib <code>Shift + A</code> bosiladi.</li><li><strong>Padding sozlash:</strong> Horizontal padding: <code>24px</code>, Vertical padding: <code>12px</code> (umumiy balandlik $16 \\times 1.2 + 24 \\approx 44\\text{--}48\\text{px}$ ga teng bo&#39;ladi).</li><li><strong>Shakl va fon:</strong> Fon rangi: To&#39;q ko&#39;k (<code>#2563EB</code>), Corner radius: <code>8px</code>.</li><li><strong>Variantlar to&#39;plami:</strong><ul><li><code>State=Enabled</code>: Asosiy ko&#39;k fon (<code>#2563EB</code>);</li><li><code>State=Hover</code>: Bir oz to&#39;qroq ko&#39;k fon (<code>#1D4ED8</code>);</li><li><code>State=Focus</code>: Ko&#39;k fon atrofida 3px qalinlikdagi ochiq havorang halqa (Focus ring: <code>#93C5FD</code>);</li><li><code>State=Active</code>: Chuqurlashgan to&#39;q ko&#39;k fon (<code>#1E40AF</code>) va masshtab 98%;</li><li><code>State=Disabled</code>: Xira kulrang fon (<code>#E2E8F0</code>), matn rangi xira kulrang (<code>#94A3B8</code>), bosish taqiqlangan.</li></ul></li></ol><hr>',19))]),i("div",z,[i("h2",T,[t(l,{name:"file-text"}),a[20]||(a[20]=o(" Tezkor nazorat savollari ",-1)),a[21]||(a[21]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[22]||(a[22]=n("<ol><li>Birlamchi (Primary) tugma bilan ikkinchi darajali (Secondary) tugma o&#39;rtasidagi asosiy farq nima? <ul><li><em>Javob:</em> Primary tugma ekrandagi eng asosiy harakatni (CTA) ifodalaydi, to&#39;liq yorqin fonga ega va odatda ekranda 1 ta bo&#39;ladi. Secondary esa yordamchi amallar (Bekor qilish) uchun ishlatilib, konturli yoki xiraroq fonga ega bo&#39;ladi.</li></ul></li><li>Mobil ekranlarda tugmaning minimal o&#39;lchami nima uchun kamida 44px bo&#39;lishi shart? <ul><li><em>Javob:</em> Inson barmog&#39;ining o&#39;rtacha teginish maydoni (touch target) hisobga olingan holda, adashmasdan va qo&#39;shni elementlarga tegib ketmasdan qulay bosishni ta&#39;minlash uchun.</li></ul></li><li>Tugmaning <code>Focus</code> holati nima uchun kerak va u kimlar uchun muhim? <ul><li><em>Javob:</em> Klaviaturadagi <code>Tab</code> tugmasi orqali interfeysda harakatlanuvchilar, sichqoncha ishlata olmaydigan yoki ko&#39;rishida nuqsoni bor (Accessibility) insonlarga hozir qaysi element tanlanganini aniq ko&#39;rsatish uchun.</li></ul></li><li>Nega dizaynerlar ilovada yangi, noodatiy ikonkalarni o&#39;ylab topmasliklari kerak? <ul><li><em>Javob:</em> Foydalanuvchilar o&#39;rganib qolgan universal vizual metaforalarga (lupa, savat, sozlamalar) ega. Yangi noaniq ikonka foydalanuvchini ikkiltiradi, xatoliklarga va tushunmovchilikka olib keladi.</li></ul></li></ol><hr>",2))]),i("div",_,[i("h2",A,[t(l,{name:"file-text"}),a[23]||(a[23]=o(" Keng tarqalgan xatolar va ularning oldini olish ",-1)),a[24]||(a[24]=i("a",{class:"header-anchor",href:"#keng-tarqalgan-xatolar-va-ularning-oldini-olish","aria-label":'Permalink to "<Icon name="file-text" /> Keng tarqalgan xatolar va ularning oldini olish"'},"​",-1))]),a[25]||(a[25]=n("<ul><li><strong>Bir ekranda bir nechta Primary tugma qo&#39;yish:</strong> Bu foydalanuvchini sarosimaga soladi. Har doim bitta ekranda faqat bitta asosiy maqsad (CTA) bo&#39;lishi kerak.</li><li><strong>Tugma matnini mavhum qilish (&quot;Bosing&quot;, &quot;Bu yerda&quot;):</strong> Tugma aniq nima sodir bo&#39;lishini aytishi lozim: <em>&quot;Buyurtma berish&quot;</em>, <em>&quot;Faylni yuklash&quot;</em>, <em>&quot;Hisobni to&#39;ldirish&quot;</em>.</li><li><strong>Past kontrastli tugmalar yaratish:</strong> Oq fonda och kulrang matn yoki yashil fonda sariq matn yozish odamlar ko&#39;zini toliqtiradi va foydalanishni qiyinlashtiradi. Har doim 4.5:1 kontrast qoidasiga amal qiling.</li></ul>",1))])])}const K=r(u,[["render",I]]);export{D as __pageData,K as default};
